import {
  Mjml,
  MjmlBody,
  MjmlButton,
  MjmlColumn,
  MjmlFont,
  MjmlHead,
  MjmlPreview,
  MjmlSection,
  MjmlSpacer,
  MjmlText,
  MjmlWrapper,
} from "@faire/mjml-react";

import type { EmailTheme } from "@/components/email/email-theme";
import { emailAsset } from "@/components/email/email-assets";
import { defaultTheme } from "@/components/email/theme-default";

export type CouponsWithContentOverlayedVariant =
  | "split"
  | "centered"
  | "code-bottom";

export interface CouponsWithContentOverlayedProps {
  theme?: EmailTheme;
  overline?: string;
  discount?: string;
  code?: string;
  expiry?: string;
  backgroundImageSrc?: string;
  buttonLabel?: string;
  buttonHref?: string;
  arrowIconSrc?: string;
  pageBackgroundColor?: string;
  headingColor?: string;
  codeBackgroundColor?: string;
  codeColor?: string;
  buttonBackgroundColor?: string;
  buttonColor?: string;
  variant?: CouponsWithContentOverlayedVariant;
}

const fontFamily =
  'Inter, ui-sans-serif, system-ui, -apple-system, "Segoe UI", sans-serif';

const backgrounds: Record<CouponsWithContentOverlayedVariant, string> = {
  centered: emailAsset("coupons/bg-image-6.jpg"),
  "code-bottom": emailAsset("coupons/bg-image-4.jpg"),
  split: emailAsset("coupons/bg-image-5.jpg"),
};

export const CouponsWithContentOverlayedSection = ({
  overline = "Our biggest sale of the year",
  discount = "20% OFF",
  code = "WINTER20OFF",
  expiry = "until 31/10/2025",
  backgroundImageSrc,
  buttonLabel = "Shop now",
  buttonHref = "https://example.com",
  headingColor = "#fffffe",
  codeBackgroundColor = "#fffffe",
  codeColor = "#030712",
  buttonBackgroundColor = "#030712",
  buttonColor = "#fffffe",
  variant = "code-bottom",
}: Omit<CouponsWithContentOverlayedProps, "theme">) => (
  <MjmlSection
    backgroundColor="#374151"
    backgroundUrl={backgroundImageSrc ?? backgrounds[variant]}
    padding="44px 24px"
  >
    <MjmlColumn padding="0">
      <MjmlText
        align="center"
        color={headingColor}
        fontFamily={fontFamily}
        fontSize="16px"
        fontWeight="600"
        lineHeight="24px"
        padding="0"
        textTransform="uppercase"
      >
        {overline}
      </MjmlText>
      <MjmlSpacer height="24px" />
      <MjmlText
        align="center"
        color={headingColor}
        fontFamily={fontFamily}
        fontSize={variant === "split" ? "36px" : "64px"}
        fontWeight="700"
        lineHeight={variant === "split" ? "44px" : "68px"}
        padding="0"
      >
        {discount}
      </MjmlText>
      <MjmlText
        align="center"
        color={codeColor}
        containerBackgroundColor={codeBackgroundColor}
        fontFamily={fontFamily}
        fontSize="18px"
        fontWeight="600"
        lineHeight="24px"
        padding="12px 18px"
      >
        {variant === "centered" ? expiry : code}
      </MjmlText>
      <MjmlSpacer height={variant === "centered" ? "182px" : "44px"} />
      <MjmlButton
        backgroundColor={buttonBackgroundColor}
        borderRadius="8px"
        color={buttonColor}
        fontFamily={fontFamily}
        fontSize="16px"
        fontWeight="500"
        href={buttonHref}
        innerPadding="14px 20px"
        lineHeight="16px"
        padding="0"
      >
        {buttonLabel} →
      </MjmlButton>
    </MjmlColumn>
  </MjmlSection>
);

export const CouponsWithContentOverlayed = ({
  pageBackgroundColor = "#f1f5f9",
  theme = defaultTheme,
  variant = "code-bottom",
  ...props
}: CouponsWithContentOverlayedProps) => (
  <Mjml>
    <MjmlHead>
      <MjmlPreview>Our biggest sale of the year</MjmlPreview>
      <MjmlFont href="https://rsms.me/inter/inter.css" name="Inter" />
    </MjmlHead>
    <MjmlBody
      backgroundColor={pageBackgroundColor}
      width={theme.containerWidth}
    >
      <MjmlWrapper padding="0">
        <CouponsWithContentOverlayedSection
          {...props}
          pageBackgroundColor={pageBackgroundColor}
          variant={variant}
        />
      </MjmlWrapper>
    </MjmlBody>
  </Mjml>
);

CouponsWithContentOverlayed.PreviewProps = {
  theme: defaultTheme,
  variant: "code-bottom",
} satisfies CouponsWithContentOverlayedProps;

const ASSET_ORIGIN = "https://www.emailcn.run";

const palettes = [
  ["4F46E5", "FFFFFF"],
  ["0F766E", "FFFFFF"],
  ["C2410C", "FFFFFF"],
  ["7E22CE", "FFFFFF"],
  ["0369A1", "FFFFFF"],
  ["BE123C", "FFFFFF"],
] as const;

const hashString = (value: string) => {
  let hash = 7;

  for (const character of value) {
    hash = (hash * 31 + (character.codePointAt(0) ?? 0)) % 2_147_483_647;
  }

  return hash;
};

const getDimensions = (path: string) => {
  if (/(?:avatar|user|headshot)/i.test(path)) {
    return [160, 160] as const;
  }
  if (/(?:logo|insignia)/i.test(path)) {
    return [320, 96] as const;
  }
  if (/(?:badge-app|badge-google)/i.test(path)) {
    return [260, 80] as const;
  }
  if (/(?:icon|btc|eth)/i.test(path)) {
    return [64, 64] as const;
  }
  if (/(?:portrait|member|team)/i.test(path)) {
    return [600, 800] as const;
  }
  if (/(?:square|product|shopping-cart)/i.test(path)) {
    return [700, 700] as const;
  }
  if (/(?:hero|footer|background|bg-|overlay|full-width)/i.test(path)) {
    return [1200, 700] as const;
  }
  if (/(?:strip|landscape|bento|category-preview)/i.test(path)) {
    return [800, 520] as const;
  }

  return [800, 600] as const;
};

const getLabel = (path: string) => {
  const fileName = path.split("/").at(-1) ?? "emailcn";

  return fileName
    .replace(/\.[^.]+$/, "")
    .replace(/^(?:logo|badge|icon)-/, "")
    .replaceAll("-", " ")
    .replaceAll(/\b\w/g, (character) => character.toUpperCase());
};

const getSeed = (path: string) =>
  `emailcn-${path
    .replace(/\.[^.]+$/, "")
    .replaceAll(/[^a-z0-9]+/gi, "-")
    .replaceAll(/^-|-$/g, "")
    .toLowerCase()}`;

export const emailAsset = (path: string) => {
  const normalizedPath = path.replace(/^\/+/, "");

  if (
    normalizedPath === "bento-grids/trend.png" ||
    normalizedPath === "bento-grids/trend-sm.png"
  ) {
    return `${ASSET_ORIGIN}/email-assets/${normalizedPath}`;
  }

  const seed = getSeed(normalizedPath);
  const hash = hashString(seed);
  const [background, foreground] =
    palettes[hash % palettes.length] ?? palettes[0];
  const [width, height] = getDimensions(normalizedPath);

  if (/(?:avatar|user|headshot|member|team)/i.test(normalizedPath)) {
    return `https://api.dicebear.com/9.x/lorelei/png?seed=${encodeURIComponent(
      seed
    )}&size=${Math.max(width, height)}&backgroundColor=${background.toLowerCase()}`;
  }

  if (/(?:trend|chart)/i.test(normalizedPath)) {
    return `${ASSET_ORIGIN}/email-assets/bento-grids/trend.png`;
  }

  if (
    /(?:icon|btc|eth|logo|insignia|badge-app|badge-google)/i.test(
      normalizedPath
    )
  ) {
    return `https://placehold.co/${width}x${height}/${background}/${foreground}.png?text=${encodeURIComponent(
      getLabel(normalizedPath)
    )}`;
  }

  return `https://picsum.photos/seed/${encodeURIComponent(
    seed
  )}/${width}/${height}.jpg`;
};
